import * as T from './vendor/three.module.js';
export function createPublicNames({container,camera,targets,occluders,player,enabled,size}){const labels=Array.from({length:3},()=>{const el=document.createElement('span');el.className='public-name';el.hidden=true;container.appendChild(el);return el;});let stamp=-Infinity;const ray=new T.Ray(),hit=new T.Vector3();const visible=o=>{while(o){if(!o.visible)return false;o=o.parent;}return true;};return {labels,update(now){if(now-stamp<250)return;stamp=now;labels.forEach(el=>el.hidden=true);if(!enabled())return;const origin=player().getWorldPosition(new T.Vector3()),viewport=size(),occupied=[];let count=0;for(const {model,name} of targets().filter(t=>t.model&&visible(t.model)).map(t=>({...t,d:t.model.getWorldPosition(new T.Vector3()).distanceTo(origin)})).filter(t=>t.d<12).sort((a,b)=>a.d-b.d)){const point=model.getWorldPosition(new T.Vector3()).add(new T.Vector3(0,2.55,0)),distance=camera.position.distanceTo(point);ray.set(camera.position,point.clone().sub(camera.position).normalize());if(occluders().some(e=>visible(e.mesh)&&e.alpha>.5&&ray.intersectBox(e.box,hit)&&hit.distanceTo(camera.position)<distance-.35))continue;const q=point.project(camera);if(q.z<0||q.z>1||Math.abs(q.x)>.85||q.y<-.7||q.y>.8)continue;const x=(q.x*.5+.5)*viewport.width,y=(-q.y*.5+.5)*viewport.height;if(occupied.some(b=>Math.abs(b.x-x)<165&&Math.abs(b.y-y)<28))continue;const el=labels[count++];el.textContent=name;el.style.left=x+'px';el.style.top=y+'px';el.hidden=false;occupied.push({x,y});if(count===3)break;}}};}
